package com.jagan.healthcare.controller;
import com.jagan.healthcare.model.Doctor; import com.jagan.healthcare.repository.DoctorRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/doctors") @CrossOrigin(origins="*") public class DoctorController { private final DoctorRepository repository; public DoctorController(DoctorRepository repository){this.repository=repository;} @GetMapping public List<Doctor> getDoctors(@RequestParam(required=false) String hospital,@RequestParam(required=false) String specialty){ if(hospital!=null&&!hospital.isBlank()&&specialty!=null&&!specialty.isBlank()) return repository.findBySpecialtyContainingIgnoreCaseAndHospitalNameIgnoreCase(specialty,hospital); if(hospital!=null&&!hospital.isBlank()) return repository.findByHospitalNameIgnoreCase(hospital); if(specialty!=null&&!specialty.isBlank()) return repository.findBySpecialtyContainingIgnoreCase(specialty); return repository.findAll(); } }
